import {realpathSync as realPublicEofPath} from 'node:fs';
function beginPublicEofOperation(){const end=process.hrtime.bigint()+15000000000n;return Object.freeze({remaining(cap=15000){assert.ok(Number.isSafeInteger(cap)&&cap>0&&cap<=15000);const left=Number((end-process.hrtime.bigint())/1000000n);if(left<=0)throw new Error('PUBLIC_EOF_OPERATION_EXPIRED');return Math.min(cap,left);}});}
function buildPublicWindowsEofActor(operation){
 assert.equal(process.platform,'win32');let directory,rawDirectory,rootIdentity,cleanupDone=false;function identity(info){const exact=value=>{if(typeof value==='bigint'&&value>=0n)return value;if(typeof value==='number'&&Number.isSafeInteger(value)&&value>=0)return BigInt(value);throw new Error('PUBLIC_EOF_ROOT_IDENTITY_UNPROVED');};assert.ok(info.isDirectory()&&!info.isSymbolicLink());const id={dev:exact(info.dev),ino:exact(info.ino)};assert.ok(id.ino>0n);return id;}function sameRoot(left,right){return left.dev===right.dev&&left.ino===right.ino;}function cleanupOwnedRoot(){if(!rawDirectory||cleanupDone)return;try{const info=lstatSync(rawDirectory,{bigint:true});if(info.isSymbolicLink()){rmSync(rawDirectory,{recursive:false,force:false,maxRetries:0});throw new Error('PUBLIC_EOF_BUILD_CLEANUP_UNCONFIRMED');}if(!rootIdentity||!sameRoot(rootIdentity,identity(info)))throw new Error('PUBLIC_EOF_BUILD_CLEANUP_UNCONFIRMED');rmSync(rawDirectory,{recursive:true,force:false,maxRetries:0});cleanupDone=true;}catch{throw new Error('PUBLIC_EOF_BUILD_CLEANUP_UNCONFIRMED');}}const state={profile:'goriq-public-eof-build-state-v1',phase:'SOURCE_INPUT',compilerClosed:null,regular:null,singleLink:null,boundedSize:null,canonical:null,sourceHash:null,nativeAuthority:false};
 try{operation.remaining();const windows=process.env.SystemRoot;assert.match(windows,/^[A-Za-z]:\\Windows$/i);const framework=join(windows,'Microsoft.NET','Framework64','v4.0.30319'),compiler=join(framework,'csc.exe');assert.ok(lstatSync(compiler).isFile()&&!lstatSync(compiler).isSymbolicLink());assert.equal(realPublicEofPath.native(compiler).toLowerCase(),compiler.toLowerCase());operation.remaining();const fixtureText=readFileSync('tests/owner-code-cutover-peer.fixture.ps1','utf8'),match=fixtureText.match(/function Get-PublicWindowsEofActorSource \{return @'\r?\n([\s\S]*?)\r?\n'@/);assert.ok(match);const source=match[1];assert.ok(Buffer.byteLength(source)>0&&Buffer.byteLength(source)<=16384);operation.remaining();state.phase='ARTIFACT_ALLOCATE';rawDirectory=mkdtempSync(join(tmpdir(),'public-eof-actor-'));rootIdentity=identity(lstatSync(rawDirectory,{bigint:true}));directory=realPublicEofPath.native(rawDirectory);assert.ok(sameRoot(rootIdentity,identity(lstatSync(rawDirectory,{bigint:true})))&&sameRoot(rootIdentity,identity(lstatSync(directory,{bigint:true}))));const sourcePath=join(directory,'actor.cs'),assemblyPath=join(directory,'actor.exe');writeFileSync(sourcePath,source,{flag:'wx'});operation.remaining();const env={SystemRoot:windows,windir:windows,PATH:join(windows,'System32'),TEMP:directory,TMP:directory};const args=['/noconfig','/nologo','/target:exe','/platform:x64','/warn:4','/warnaserror+','/reference:'+join(framework,'System.dll'),'/reference:'+join(framework,'System.Xml.dll'),'/reference:'+join(framework,'System.Runtime.Serialization.dll'),'/out:'+assemblyPath,sourcePath];state.phase='COMPILER_START';const r=spawnSync(compiler,args,{env,cwd:directory,encoding:'utf8',timeout:operation.remaining(3000),maxBuffer:8192,windowsHide:true,shell:false,killSignal:'SIGKILL'});state.phase='COMPILER_RETURN';console.log('GORIQ_PUBLIC_EOF_COMPILER_STATE '+JSON.stringify({phase:'RETURN',exitClass:r.status===0?'ZERO':Number.isInteger(r.status)?'NONZERO':'UNKNOWN',errorClass:r.error?.code==='ETIMEDOUT'?'TIMEOUT':r.error?'REFUSED':'NONE',stdoutData:Boolean(r.stdout),stderrData:Boolean(r.stderr),nativeAuthority:false}));assert.equal(r.error,undefined,'PUBLIC_EOF_COMPILER_REFUSED');assert.equal(r.status,0,'PUBLIC_EOF_COMPILER_FAILED');assert.equal(r.signal,null,'PUBLIC_EOF_COMPILER_NOT_CLOSED');assert.equal(r.stdout,'','PUBLIC_EOF_COMPILER_STDOUT');assert.equal(r.stderr,'','PUBLIC_EOF_COMPILER_STDERR');state.compilerClosed=true;operation.remaining();for(const path of [sourcePath,assemblyPath]){state.phase=path===sourcePath?'SOURCE_FILE':'ASSEMBLY_FILE';state.regular=null;state.singleLink=null;state.boundedSize=null;state.canonical=null;const info=lstatSync(path);state.regular=info.isFile()&&!info.isSymbolicLink();state.singleLink=info.nlink===1;state.boundedSize=info.size>0&&info.size<=1048576;assert.ok(state.regular&&state.singleLink&&state.boundedSize);state.canonical=realPublicEofPath.native(path).toLowerCase()===path.toLowerCase();assert.equal(state.canonical,true);}state.phase='SOURCE_READBACK';const sourceSha256=createHash('sha256').update(readFileSync(sourcePath)).digest('hex');state.phase='ASSEMBLY_READBACK';const assemblySha256=createHash('sha256').update(readFileSync(assemblyPath)).digest('hex');state.phase='SOURCE_DIGEST';state.sourceHash=sourceSha256===createHash('sha256').update(source).digest('hex');assert.equal(state.sourceHash,true);operation.remaining();state.phase='COMPLETE';console.log('GORIQ_PUBLIC_EOF_BUILD_STATE '+JSON.stringify(state));return {directory,cleanupDirectory:rawDirectory,cleanup:cleanupOwnedRoot,sourceSha256,assemblySha256,compilerExited:true};
 }catch{console.log('GORIQ_PUBLIC_EOF_BUILD_STATE '+JSON.stringify(state));cleanupOwnedRoot();throw new Error('PUBLIC_EOF_ACTOR_BUILD_REFUSED');}
}

