 for(const group of [0,1]){const operation=process.platform==='win32'?beginPublicEofOperation():null;let actor;try{if(operation)actor=buildPublicWindowsEofActor(operation);const actorArgs=actor?['-PublicEofActorRoot',actor.directory,'-PublicEofActorSourceHash',actor.sourceSha256,'-PublicEofActorAssemblyHash',actor.assemblySha256]:[];const child=spawnSync(shell,['-NoLogo','-NoProfile','-NonInteractive','-File','tests/owner-code-cutover-peer.fixture.ps1','-Root',process.cwd(),'-OwnedTransport','-ClosedChannel','-TransportGroup',String(group),...actorArgs],{input:JSON.stringify({encoded:encode(g),environment,now:new Date(now).toISOString(),nodeExecutable:process.execPath}),env:actor?{...process.env,TEMP:dirname(actor.directory),TMP:dirname(actor.directory)}:process.env,encoding:'utf8',timeout:operation?operation.remaining():15000,maxBuffer:16384});assert.equal(child.error,undefined);assert.equal(child.status,0,child.stdout+child.stderr);assert.equal(child.stderr,'');const result=JSON.parse(child.stdout);assert.equal(result.pass,true);assert.equal(result.authority,false);assert.equal(result.actualNativeWindowsCalls,actor?null:0);assert.equal(result.publicNativeFixtureActor,Boolean(actor));assert.equal(result.actualProductTaskAccountDpapiCalls,0);assert.equal(result.ownedPublicChildren,1);cases.push(...result.transportCases.map(row=>row.case));}finally{if(actor)actor.cleanup();}if(operation)operation.remaining();}
