// Public SQLite corpus: RFC8032 public keys, fake38 and sentinel history only.
// Only this fixture writer mutates SQLite; the new observer receives opaque
// already-captured core9 handles and has no path/SQL/clock/callback parameter.
const fleetAt='2026-11-07T04:00:00.000Z',fleetLater='2026-11-07T04:01:00.000Z';
const fleetKey=hex=>`-----BEGIN PUBLIC KEY-----\n${Buffer.from('302a300506032b6570032100'+hex,'hex').toString('base64')}\n-----END PUBLIC KEY-----\n`;
const fleetPublicKey=fleetKey('d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a');
const fleetOtherKey=fleetKey('3d4017c3e843895a92b70aa74d1b7ebc9c982ccf2ec4968cc0cd55f12af4660c');
function publicPeerFleet(t,{count=38,present=false}={}){
 const dir=mkdtempSync(join(tmpdir(),'peer-original38-public-')),path=join(dir,'PRIVATE-SENTINEL-fleet.db');let db,closed=false;
 const state={generatedAt:fleetAt,fleet:Array.from({length:count},(_,i)=>({id:`PRIVATE-SENTINEL-node-${i}`,label:`Public fake${i}`,kind:'android',status:'ready',capabilities:['device-status'],policy:{allowPaidServices:false,allowDestructiveActions:false,allowExternalPublication:false,allowRemoteControl:false,requireHumanForLockedDevice:true},telemetry:{checkedAt:fleetAt,batteryPercent:90},enrollment:'full',lastSeenAt:fleetAt})),tasks:[{id:'PRIVATE-SENTINEL-task',idempotencyKey:'PRIVATE-SENTINEL-command',type:'device-status',payload:{text:'PRIVATE-SENTINEL-payload'},status:'queued',requiredCapabilities:['device-status'],priority:'normal',requiresOnline:false,attempts:0,maxAttempts:3,createdAt:fleetAt,updatedAt:fleetAt}],activeTakeovers:[],audit:[{id:'PRIVATE-SENTINEL-history',at:fleetAt,actor:'owner',action:'queued'}],stats:{registered:count,ready:count,offline:0,needsHuman:0,queued:1,running:0,completed:0,failed:0}};
 function open(){db=new DatabaseSync(path);closed=false;db.exec('PRAGMA journal_mode=WAL; CREATE TABLE jarvis_state (id INTEGER PRIMARY KEY CHECK (id = 1), payload TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT; CREATE TABLE jarvis_worker_identity (node_id TEXT PRIMARY KEY, payload TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT; CREATE TABLE jarvis_worker_nonce (node_id TEXT NOT NULL, nonce TEXT NOT NULL, expires_at INTEGER NOT NULL, PRIMARY KEY (node_id, nonce)) STRICT; CREATE INDEX jarvis_worker_nonce_expires_at ON jarvis_worker_nonce (expires_at);');db.prepare('INSERT INTO jarvis_state VALUES(1,?,?)').run(JSON.stringify(state),fleetAt);for(const node of state.fleet)db.prepare('INSERT INTO jarvis_worker_identity VALUES(?,?,?)').run(node.id,JSON.stringify({nodeId:node.id,publicKeyPem:fleetPublicKey,enrolledAt:fleetAt,algorithm:'ed25519'}),fleetAt);db.prepare('INSERT INTO jarvis_worker_nonce VALUES(?,?,?)').run(state.fleet[0].id,'PRIVATE-SENTINEL-nonce',Date.now()+3600000);}
 open();const options={schemaProfile:'jarvis-control-plane-sqlite-v1',databaseBinding:{path,configSha256:'a'.repeat(64),taskSha256:'b'.repeat(64),releaseRevision:'c'.repeat(40)},cohortAuthority:{kind:'approved-active-capture',approvalSha256:'d'.repeat(64),expectedCount:count},pcSidecars:{profile:'jarvis-pc-sidecars-v1',expectedTaskFile:present?'present':'absent',expectedObservationFile:present?'present':'absent'}};
 function writePc(){writeFileSync(path+'.pc-tasks.json',JSON.stringify({version:1,tasks:[],savedAt:fleetAt},null,2)+'\n');writeFileSync(path+'.pc-observations.json',JSON.stringify({version:1,records:[],savedAt:fleetAt},null,2)+'\n');}
 if(present)writePc();const close=()=>{if(!closed){db.close();closed=true;}};t.after(()=>{close();rmSync(dir,{recursive:true,force:true});});
 return {path,options,state,capture:()=>captureFleetSnapshot(path,options),save:()=>db.prepare('UPDATE jarvis_state SET payload=?,updated_at=? WHERE id=1').run(JSON.stringify(state),state.generatedAt),identity:(key)=>db.prepare('UPDATE jarvis_worker_identity SET payload=? WHERE node_id=?').run(JSON.stringify({nodeId:state.fleet[0].id,publicKeyPem:key,enrolledAt:fleetAt,algorithm:'ed25519'}),state.fleet[0].id),replace:()=>{db.exec('PRAGMA wal_checkpoint(TRUNCATE)');close();renameSync(path,path+'.old');open();},writePc,close,erase:()=>{close();rmSync(dir,{recursive:true,force:true});}};
}
function original38Observer(){assert.equal(typeof native.createCutoverPreservationDataObserver,'function');assert.equal(typeof native.acceptCutoverPreservationData,'function');return native.createCutoverPreservationDataObserver();}
const preserveReject=fn=>assert.throws(fn,/^Error: ROTATION_CUTOVER_PRESERVATION_DATA_REJECTED$/);
function original38Begin(f){const first=f.capture();assert.equal(fleetSnapshotSummary(first).fleetCount,38);assert.equal(compareFleetSnapshots(first,f.capture()).status,'PASS');const token=original38Observer();const result=native.acceptCutoverPreservationData(token,'capture-before-cutover',first);assert.equal(result.accepted,true);assert.equal(result.nativeAuthority,false);assert.equal(native.acceptCutoverPreservationData(token,'after-cutover',f.capture()).accepted,true);return token;}
function safePreservationData(value){assert.doesNotMatch(JSON.stringify(value),/PRIVATE-SENTINEL|BEGIN PUBLIC KEY|fleet\.db|"(?:path|payload|publicKeyPem|ownerSid|clock)":/);}

test('pure original38 observer preserves one pre-cutover opaque baseline and never recaptures at before-rotation',t=>{
 const f=publicPeerFleet(t),token=original38Begin(f);assert.equal(Object.isFrozen(token),true);assert.deepEqual(Reflect.ownKeys(token),[]);
 f.state.fleet[0].label='PUBLIC_CHANGED_LABEL';f.save();const result=native.acceptCutoverPreservationData(token,'before-rotation',f.capture());assert.equal(result.accepted,false);assert.equal(result.comparison.status,'FAIL');assert.ok(result.comparison.reasonCodes.includes('FLEET_METADATA_CHANGED'));assert.equal(result.summary.fleetCount,38);assert.equal(result.nativeAuthority,false);assert.equal(Object.isFrozen(result),true);safePreservationData(result);
 f.state.fleet[0].label='Public fake0';f.save();const recovery=native.acceptCutoverPreservationData(token,'after-rollback',f.capture());assert.equal(recovery.accepted,true);safePreservationData(recovery);preserveReject(()=>native.acceptCutoverPreservationData(token,'capture-before-cutover',f.capture()));
});
