test('actual original clock endpoint DATA matches frozen rational edges and preserves original reference and sticky-denial taxonomy',()=>{
 const shell=process.platform==='win32'?join(process.env.SystemRoot,'System32/WindowsPowerShell/v1.0/powershell.exe'):'pwsh';
// Frozen research oracle only, never imported by product or used as authority.
const T=10000000n,MAX=9223372036854775807n,UTC_MAX=3155378975999999999n;
const floor=(n,d)=>{if(n<0n||d<=0n)throw Error('ORACLE_RANGE');return n/d;};
const min=(...v)=>v.reduce((a,b)=>a<b?a:b),max=(a,b)=>a>b?a:b;
function endpointOracle(v){
 const {originUtc:O,origin:P,frequency:F,hardEnd:H,sampleUtc:U,pre:B,sample:S,previousHard}=v;
 if([O,H,U].some(n=>n<0n||n>UTC_MAX)||P<0n||P>MAX||F<=0n||F>MAX||B<P||B>MAX||S<B||S>MAX||U<O||H<=O||H-O>900n*T||H<=U)return {kind:'INTEGRITY_OR_ORIGINAL_BOUND_REFUSAL'};
 const nominal=P+floor((H-O)*F,T),utcCap=B+floor((H-U)*F,T);
 if(nominal>MAX)return {kind:'UNREPRESENTABLE_DATA'};
 const hard=previousHard===undefined?min(nominal,utcCap):min(nominal,utcCap,previousHard),forward=max(0n,hard-120n*F);
 if(hard<=S)return {kind:'CONSERVATIVE_CUT_REACHED',originalHardTerminalClaimed:false};
 return {kind:'DATA',nominal:String(nominal),utcCap:String(utcCap),hard:String(hard),forward:String(forward),remainingHard:String(hard-S),remainingForward:String(max(0n,forward-S)),nativeAuthority:false};
}
const epoch=639000000000000000n;
const endpointVectors=[
 ['unchanged-900', {originUtc:epoch,origin:100000000n,frequency:10000000n,hardEnd:epoch+900n*T,sampleUtc:epoch+10n*T,pre:200000000n,sample:200000010n}],
 ['official-older-start-880', {originUtc:epoch,origin:100000000n,frequency:10000000n,hardEnd:epoch+880n*T,sampleUtc:epoch+10n*T,pre:200000000n,sample:200000010n}],
 ['one-utc-tick-fraction', {originUtc:epoch+1n,origin:100000000n,frequency:10000003n,hardEnd:epoch+880n*T,sampleUtc:epoch+10n*T+2n,pre:200000030n,sample:200000040n}],
 ['frequency-odd-3', {originUtc:epoch,origin:1000n,frequency:3n,hardEnd:epoch+900n*T,sampleUtc:epoch+1n,pre:1000n,sample:1000n}],
 ['sampling-delay-conservative-before-utc', {originUtc:epoch,origin:0n,frequency:1000n,hardEnd:epoch+900n*T,sampleUtc:epoch+100n*T,pre:1000n,sample:5000n}],
 ['sampling-delay-new-only-cut', {originUtc:epoch,origin:0n,frequency:1000n,hardEnd:epoch+900n*T,sampleUtc:epoch+850n*T,pre:1000n,sample:60000n}],
 ['forward-absolute-still-positive-remainder-zero', {originUtc:epoch,origin:1000000n,frequency:1000n,hardEnd:epoch+900n*T,sampleUtc:epoch+800n*T,pre:1800000n,sample:1800000n}],
 ['forward-raw-clamped-zero', {originUtc:epoch,origin:0n,frequency:1000n,hardEnd:epoch+100n*T,sampleUtc:epoch,pre:0n,sample:0n}],
 ['sub-one-stamp-tick-positive-old-clock', {originUtc:epoch,origin:1000n,frequency:1n,hardEnd:epoch+T,sampleUtc:epoch+T-1n,pre:1000n,sample:1000n}],
 ['nominal-exact-int64-max', {originUtc:epoch,origin:MAX-9000000000n,frequency:10000000n,hardEnd:epoch+900n*T,sampleUtc:epoch,pre:MAX-9000000000n,sample:MAX-9000000000n}],
 ['nominal-int64-overflow-refuses', {originUtc:epoch,origin:MAX-8999999999n,frequency:10000000n,hardEnd:epoch+900n*T,sampleUtc:epoch,pre:MAX-8999999999n,sample:MAX-8999999999n}],
 ['product-overflows-int64-quotient-fits', {originUtc:epoch,origin:0n,frequency:10000000000n,hardEnd:epoch+900n*T,sampleUtc:epoch,pre:0n,sample:0n}],
 ['frequency-int64-max-unrepresentable', {originUtc:epoch,origin:0n,frequency:MAX,hardEnd:epoch+900n*T,sampleUtc:epoch,pre:0n,sample:0n}],
 ['previous-utc-cap-cannot-increase-after-stall', {originUtc:epoch,origin:0n,frequency:1000n,hardEnd:epoch+900n*T,sampleUtc:epoch+100n*T,pre:20000n,sample:20000n,previousHard:801000n}],
 ['fractional-floor-deadline-equality-refuses', {originUtc:epoch,origin:0n,frequency:3n,hardEnd:epoch+T,sampleUtc:epoch,pre:0n,sample:3n}],
];

 const shift=BigInt(now)*10000n+621355968000000000n-epoch;
 const vectors=endpointVectors.map(([id,input])=>{const v={...input};for(const key of ['originUtc','hardEnd','sampleUtc'])v[key]+=shift;return {id,...Object.fromEntries(Object.entries(v).map(([k,n])=>[k,String(n)])),expected:endpointOracle(v)};});
 const g=grant();for(const name of Object.keys(g.sourceHashes))g.sourceHashes[name]=createHash('sha256').update(readFileSync(name)).digest('hex');const child=spawnSync(shell,['-NoLogo','-NoProfile','-NonInteractive','-File','tests/owner-code-cutover-peer.fixture.ps1','-Root',process.cwd(),'-ClockEndpointData'],{input:JSON.stringify({encoded:encode(g),environment,now:new Date(now).toISOString(),vectors}),encoding:'utf8',timeout:process.platform==='win32'?60000:15000,maxBuffer:131072});assert.equal(child.error,undefined);assert.equal(child.status,0,child.stdout+child.stderr);assert.equal(child.stderr,'');const r=JSON.parse(child.stdout);assert.equal(r.pass,true);assert.equal(r.actualOriginalRegistration,true);assert.equal(r.actualNativeCalls,0);assert.equal(r.nativeAuthority,false);assert.equal(r.qpcAssociationVerified,false);assert.equal(r.minimaPreserved,true);assert.equal(r.vectors.length,15);assert.equal(r.negative.length,33);
 const fields=['schemaVersion','profile','sourceRevision','originalGrantSha256','workflowRunId','officialJobId','originUtcTicks','originStamp','frequency','sampleUtcTicks','sampleStamp','hardEndUtcTicks','hardStampEndpoint','forwardStampEndpoint','remainingHardTicks','remainingForwardTicks','nativeAuthority','effectCapability','qpcAssociationVerified'];
 for(const [i,row]of r.vectors.entries()){const v=vectors[i];assert.equal(row.id,v.id);if(v.expected.kind!=='DATA'){assert.equal(row.refused,true);assert.equal(row.originalTerminal,v.id==='fractional-floor-deadline-equality-refuses');if(v.id==='sampling-delay-new-only-cut')assert.equal(row.originalHardMsAfterConservativeRefusal,50000);continue;}const d=row.value;assert.deepEqual(Object.keys(d).sort(),fields.toSorted());assert.equal(d.profile,'goriq-original-clock-endpoints-data-v1');assert.equal(d.schemaVersion,1);for(const flag of ['nativeAuthority','effectCapability','qpcAssociationVerified'])assert.equal(d[flag],false);for(const key of ['originUtcTicks','originStamp','frequency','sampleUtcTicks','sampleStamp','hardEndUtcTicks','hardStampEndpoint','forwardStampEndpoint','remainingHardTicks','remainingForwardTicks'])assert.match(d[key],/^(?:0|[1-9][0-9]*)$/);assert.equal(d.originUtcTicks,v.originUtc);assert.equal(d.originStamp,v.origin);assert.equal(d.frequency,v.frequency);assert.equal(d.sampleUtcTicks,v.sampleUtc);assert.equal(d.sampleStamp,v.sample);assert.equal(d.hardEndUtcTicks,v.hardEnd);for(const [actual,expected]of [['hardStampEndpoint','hard'],['forwardStampEndpoint','forward'],['remainingHardTicks','remainingHard'],['remainingForwardTicks','remainingForward']])assert.equal(d[actual],v.expected[expected],v.id);assert.equal(d.sourceRevision,g.sourceRevision);assert.equal(d.originalGrantSha256,createHash('sha256').update(JSON.stringify(g)).digest('hex'));}
 const reviewedCuts=['null-previous-hard','null-all-minima','coherent-larger-hard-forward-zero','fresh-lifetime-same-genuine-pins','clear-terminal-after-bookkeeping-refusal','first-reader-terminal'];
 const expectedReview=reviewedCuts.map(id=>({id,firstHard:'101000',firstForward:'0',refused:true,utcSamples:id==='first-reader-terminal'?1:0,stampSamples:id==='first-reader-terminal'?1:0,frequencySamples:id==='first-reader-terminal'?1:0,originalTerminal:id==='first-reader-terminal',stickyAfterRepair:true}));
 assert.deepEqual(r.reviewRegressions,expectedReview,`FROZEN_REVIEW_REGRESSIONS ${JSON.stringify(r.reviewRegressions)}`);
 assert.doesNotMatch(JSON.stringify(r),/PRIVATE_BAD_STAMP|S-1-5-21|C:\\/);
});

